OUTPUT = Path("output/doc/65130641_Riskie_Thesis_v2_revised_final.docx")


def normalized(text: str) -> str:
    return " ".join((text or "").split())


def set_paragraph_text(paragraph, text: str) -> None:
    """Replace paragraph text while retaining its first run's direct formatting."""
    if paragraph.runs:
        paragraph.runs[0].text = text
        for run in paragraph.runs[1:]:
            run.text = ""
    else:
        paragraph.add_run(text)


def copy_paragraph_format(source, destination) -> None:
    if destination._p.pPr is not None:
        destination._p.remove(destination._p.pPr)
    if source._p.pPr is not None:
        destination._p.insert(0, deepcopy(source._p.pPr))
    if source.runs and destination.runs and source.runs[0]._r.rPr is not None:
        destination.runs[0]._r.insert(0, deepcopy(source.runs[0]._r.rPr))


def find_paragraph(document, exact_text: str):
    matches = [p for p in document.paragraphs if normalized(p.text) == normalized(exact_text)]
    if len(matches) != 1:
        raise RuntimeError(f"Expected one paragraph for {exact_text!r}, found {len(matches)}")
    return matches[0]


def replace_exact(document, old: str, new: str, changes: list[str]) -> None:
    paragraph = find_paragraph(document, old)
    set_paragraph_text(paragraph, new)
    changes.append(f"Replaced: {normalized(old)[:90]}")


def set_cell_text(cell, text: str, bold: bool = False) -> None:
    cell.text = ""
    paragraph = cell.paragraphs[0]
    paragraph.alignment = WD_ALIGN_PARAGRAPH.CENTER
    run = paragraph.add_run(text)
    run.bold = bold


def prevent_row_split(row) -> None:
    tr_pr = row._tr.get_or_add_trPr()
    cant_split = OxmlElement("w:cantSplit")
    tr_pr.append(cant_split)


def set_repeat_table_header(row) -> None:
    tr_pr = row._tr.get_or_add_trPr()
    tbl_header = OxmlElement("w:tblHeader")
    tbl_header.set(qn("w:val"), "true")
    tr_pr.append(tbl_header)


def insert_before(target, text: str, template):
    paragraph = target.insert_paragraph_before(text)
    copy_paragraph_format(template, paragraph)
    return paragraph


